// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// ============ Enums ============

enum CabalPhase {
    Presale,    // Accepting contributions
    Active,     // Token deployed, governance active
    Paused,     // Governance paused (emergency)
    Closed      // Dissolved - inert, read-only
}

enum ProposalState {
    Pending,
    Active,
    Succeeded,
    Defeated,
    Executed,
    Cancelled,
    Expired     // Proposal succeeded but wasn't executed within execution window
}

enum ActivityType {
    CabalCreated,
    Contributed,
    VotedLaunch,
    Launched,
    Claimed,
    Staked,
    Unstaked,
    Bought,
    Sold,
    ProposalCreated,
    ProposalVoted,
    ProposalExecuted,
